-- WORKOUTS TABLE
-- Stores each account
CREATE TABLE workouts (
    -- UNIQUE ID automatically generated
    id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    -- Workout name
    name TEXT NOT NULL CHECK (length(trim(name)) > 0),

    -- Workout must have a date
    workout_date DATE NOT NULL,

    -- Workout must be inputted at a certain time
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    -- Timestamp when workout was last updated
    updated_at TIMESTAMPTZ,

    -- Timestamp used for soft deletion
    deleted_at TIMESTAMPTZ,

    -- Program that is in the workout
    program_id INTEGER REFERENCES programs(id) ON DELETE SET NULL
    
);


CREATE TABLE exercises (
    -- UNIQUE ID automatically generated
    id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    -- Exercise Name
    name TEXT NOT NULL CHECK (length(trim(name)) > 0) UNIQUE,
);

CREATE TABLE programs (
    -- UNIQUE ID automatically generated
    id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    -- Program name
    
    name TEXT NOT NULL CHECK (length(trim(name)) > 0) UNIQUE    

);

CREATE TABLE workout_exercises (
    id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    workout_id INTEGER NOT NULL REFERENCES workouts(id),

    exercise_id INTEGER NOT NULL REFERENCES exercises(id),
);

CREATE TABLE program_exercises (
    id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    program_id INTEGER NOT NULL REFERENCES programs(id),

    exercise_id INTEGER NOT NULL REFERENCES exercises(id),

    UNIQUE (program_id, exercise_id)
);

CREATE TABLE exercise_sets (
    id INTEGER GENERATED AS ALWAYS AS IDENTITY PRIMARY KEY,

    workout_exercise_id INTEGER NOT NULL REFERENCES workout_exercises(id),
    
    set_number INTEGER NOT NULL CHECK (set_number > 0),

    reps INTEGER NOT  NULL CHECK (reps >= 0),

    weight_kg NUMERIC(7,2) CHECK (weight_kg >= 0),

    UNIQUE (workout_exercise_id, set_number)
);














































-- CATEGORIES TABLE
-- Stores transaction categories
CREATE TABLE categories (

    -- Unique ID automatically generated by PostgreSQL
    id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    -- Category name must exist, cannot be empty, and cannot be duplicated
    name TEXT NOT NULL UNIQUE CHECK (length(name) > 0),

    -- Timestamp used for soft deletion
    deleted_at TIMESTAMPTZ
);


-- TRANSACTIONS TABLE
-- Stores money entering or leaving an account
CREATE TABLE transactions (

    -- Unique ID automatically generated by PostgreSQL
    id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    -- Account this transaction belongs to
    account_id INTEGER NOT NULL REFERENCES accounts(id),

    -- Transaction name
    name TEXT NOT NULL CHECK (length(name) > 0),

    -- Positive = money in, negative = money out, zero not allowed
    amount NUMERIC(12,2) NOT NULL CHECK (amount != 0),

    -- Date the transaction actually occurred
    transaction_date DATE NOT NULL,

    -- Timestamp when the transaction was created
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    -- Timestamp when the transaction was last updated
    updated_at TIMESTAMPTZ,

    -- Optional category for the transaction
    category_id INTEGER REFERENCES categories(id),

    -- Timestamp used for soft deletion
    deleted_at TIMESTAMPTZ,

    -- Transaction type
    transaction_type TEXT NOT NULL DEFAULT 'regular'
);